D=Path(__file__).resolve().parent;R=D.parents[2];s=json.load(open(D/'source.json'));profiles=json.load(open(D/'source-profiles.json'));questions=[q for q in s['record'][':knowledge-point/questions'] if ':question/math-academy-id' in q]
