rows=['# Classification at immutable basis2275','','MA originals:12; independent inventory:11 exact records in independent-inventory.json, excluded from every MA count. Canonical example e-385 is lesson context, not a practice question. Frozen source, topic and lesson wrappers retain their complete captured records.','','| Source | Rating | Input/response family | Fields | Bank | Plots |','|---|---|---|---|---|---|']
for q in questions:
 mid=q[':question/math-academy-id'];level=q.get(':question/difficulty',{}).get(':db/ident','absent/unrated');fields=q.get(':question/answer-fields',[])
 rows.append('| '+mid+' | '+level+' | '+q[':question/problem'].replace('|',r'\|').replace('\n',' ')+' | '+str([(f[':answer-field/key'],f[':answer-field/type'][':db/ident']) for f in fields])+' | '+str([len(f[':answer-field/choices']) for f in fields])+' | none |')
rows+=['','Different scalar signs, variable spellings and complete banks remain separate profiles while task novelty is measured by actual integrands. Easy: scalar csc² recall, including fraction and blank response. Moderate: two-term sum or product expansion. Hard: three directly recalled primitives. No substitution, trig identities, argument scaling, definite endpoints, new derivatives or domains crossing poles.','', 'Missing-field q113948/q113952/q113958 remain fieldless raw; normal completions have authored radio banks. Missing-key/rating/solution q2037/q49093 stay absent and ineligible raw. Undefined v(t) q143522/q167569 stay literal raw; the normal blank adds the definition evidenced by the main calculation. q71666 retains two malformed options raw; normal sine-difference uses a fully separate authored bank. q113958 has a missing sin argument in the recall; normal solution uses the argument established by the prompt, main stages and lesson.']
